static int project_save_as(uint32_t slot, const char *name)
{
    project_t *p = &proj_scratch;
    int kr;
    if (transport_busy()) {                            /* a flash erase silences the audio and stalls the */
        ui_message("STOP TO SAVE");                     /* sequencer (storage_hw.c): only while stopped */
        return 1;
    }
    if ((kr = keep_all()) != 0) {                      /* (phase 5) the tracks' patterns first: a project names them */
        ui_way(kr == 1 ? "PATTERNS FULL" : "SAVE ERROR", kr == 1 ? WAY_PATTERNS : "");
        return kr;
    }
    project_capture(p);
    if (name) {
        memset(p->name, 0, sizeof p->name);
        memcpy(p->name, name, str_len(name) < PROJ_NAME_LEN ? str_len(name) : PROJ_NAME_LEN);
    }
    proj_wire_gen++;
    if (!proj_pack2(&proj_wire, p, PROJ_SKF)) { ui_message("SAVE FORMAT ERROR"); return 2; }

#if FELUCCA_FLASH
    if (flash_ok) {
        if (st_save(OBJ_PROJECT0 + (slot & 3u), &proj_wire, PROJ_SKF->size)) {
            ui_message("SAVE ERROR");
            return 2;
        }
        memcpy(&proj_slot[slot & 3u], &proj_wire, sizeof proj_wire);
        proj_name_get(proj_name, (const uint8_t *)p->name);
        proj_cur = (uint8_t)(slot & 3u);
        project_clean();
        ui_message("SAVED");
        return 0;
    }
#endif
    memcpy(&proj_slot[slot & 3u], &proj_wire, sizeof proj_wire);
    proj_name_get(proj_name, (const uint8_t *)p->name);
    proj_cur = (uint8_t)(slot & 3u);
    project_clean();
    ui_message("SAVED UNTIL POWER OFF");
    return 0;
}

/* (2.0, #44) a LOOP launch of entry e for track k, playing: on a chain's part before its last, it waits for the chain's
 * end as for a pattern's (song_poll stages it on the last part), one of the user's staged before dropped, the chain's
 * own next kept; 1 waiting */
static int chain_wait(uint32_t k, uint32_t e)
{
    uint32_t b0, b1, c;
    bank_poll_trk(k);                              /* (a swap just made: the track on what came in) */
    c = lists.cur[k] % NENT;
    if (!ent_block(k, c, &b0, &b1) || c == b1)
        return 0;
    if (launch_q[k].armed && !launch_q[k].adv) {
        launch_q[k].armed = 0;
        RING_PUBLISH();
    }
    chain_go[k] = (uint8_t)(e + 1u);
    bk.gen++;
    return 1;
}

