static void eu_fit(const track_t *t)                    /* the values inside LEN */
{
    uint32_t len = tl_len(t);
    if (!eu.steps || eu.steps > len)
        eu.steps = (uint8_t)(len < 16u ? len : 16u);
    if (eu.hits > eu.steps)
        eu.hits = eu.steps;
    eu.rot = (uint8_t)(eu.rot % eu.steps);
}

/* the accent of lane l at step i (on 1, off 0, toggled 2); an accent on an empty lane adds the hit */
static void grid_acc(track_t *t, uint32_t i, uint32_t l, uint32_t on)
{
    step_t *s = &t->step[i % NSTEP];
    uint32_t b = 1u << (l % NLANE);
    if (on == 2u)
        on = !(step_accents(s) & b);
    if (on)
        grid_hit(t, i, l, 1);
    if (!(step_lanes(s) & b))
        return;
    grid_own(s, l % NLANE);
    if (s->flags & SF_ACCENT) {                  /* a step accent: each hit's own from now on */
        s->acc |= s->hit;
        s->flags &= (uint8_t)~SF_ACCENT;
    }
    s->acc = (uint8_t)(on ? s->acc | b : s->acc & ~b);
}

/* ---- 1.1.5: SEQ > AUTO LIST (ui_input.c ev_*): the records of a track as a list, edited one by one ---- */
/* the record of track t on step / id (either kind): its index, -1 none */
static int32_t motion_find(const track_t *t, uint32_t step, uint32_t id)
{
    uint32_t i, place = trk_index(t) << 6 | step;
    for (i = 0; i < motion.count; i++)
        if (motion.event[i].place == place && MOTION_ID(&motion.event[i]) == id)
            return (int32_t)i;
    return -1;
}

