/* ------------------------------------------------------------ routing --- */
/* the modulators of each FM6 operator (bit k: operator k + 1) of algorithm a, its carriers, and its feedback one,
 * read from fm6_core.c FM6_ALG as the renderer walks it (the sixth operator first, buses written then read) */
static void fm6_routes(uint32_t a, uint32_t *mods, uint32_t *car, uint32_t *fbop)
{
    uint32_t bus[3] = {0, 0, 0}, k;
    *car = 0;
    *fbop = 0;
    for (k = 0; k < 6u; k++) {
        uint32_t f = FM6_ALG[a][k], op = 6u - k, in = (f >> 4) & 3u, out = f & 3u;
        mods[op] = in ? bus[in] : 0u;
        if ((f & 0xc0u) == 0xc0u)
            *fbop = op;
        if (out)
            bus[out] = (f & 4u ? bus[out] : 0u) | 1u << (op - 1u);
        else
            *car |= 1u << (op - 1u);
    }
}

static void analog_render(track_t *t, voice_t *v, int32_t *out, uint32_t n, const vmod_t *m)
{
    if (t->p[P_E0] >= AW_SYNC)
        analog_render_x(t, v, out, n, m);
    else
        analog_osc(t, v, out, n, m);
}

/* 2^(st16 / 192) in Q16 (st16 in 1/16 semitone), clamped to 1/16 .. 16.
 * Divisions by constants are written as multiplies: -Os keeps them as divides */
static uint32_t fmt_ratio(int32_t st16)
{
    int32_t o, k;
    uint32_t r;
    st16 = clamp(st16, -4 * 192, 4 * 192 - 1) + 4 * 192;   /* 0 .. 8 octaves */
    o = (st16 * 2731) >> 19;                            /* / 192, exact for 0 .. 1535 */
    k = st16 - o * 192;
    r = SEMI_Q16[k >> 4] + (((SEMI_Q16[(k >> 4) + 1] - SEMI_Q16[k >> 4]) * (uint32_t)(k & 15)) >> 4);
    return o >= 4 ? r << (o - 4) : r >> (4 - o);
}

static uint32_t px_isqrt64(uint64_t v)                    /* floor(sqrt(v)) */
{
    uint64_t r = 0, b = (uint64_t)1 << 62;
    while (b > v)
        b >>= 2;
    while (b) {
        if (v >= r + b) {
            v -= r + b;
            r = (r >> 1) + b;
        } else {
            r >>= 1;
        }
        b >>= 2;
    }
    return (uint32_t)r;
}

static void drum_note_on(track_t *t, voice_t *v)
{
    drum_lane_t *K = drum_kit_of(t), *L;
    uint32_t i = (uint32_t)(v - t->v), role, lane, u;
    int32_t st;
    if (!K || i >= NVOICE)
        return;
    role = drum_gm(t->p, v->note, &st);
    lane = drum_lane(v->note);
    L = &K[(uint32_t)v->s[0] & (DV_NLANE - 1u)];
    u = drum_user(t->p);
    if (u && v->env && L->owner == i + 1u && (v->s[5] & 0x8000) && v->s[6] != 1) {   /* ((#35) its sample still */
        int32_t o = v->s[3] + (((v->s[1] - v->s[3]) * (int32_t)(v->ph[1] >> 1)) >> 15);   /* playing (env: sounding, */
        o = t->p[P_E2] < 64 ? (int32_t)v->ph[2] : (o * (v->s[7] >> 9)) >> 15;    /* voice_start): where it is now, */
        v->s[4] = clamp(o + v->s[4], -32767, 32767);    /* the new hit's declick (drum_smp) */
    } else {
        v->s[4] = 0;
    }
    if (L->owner == i + 1u)                              /* this voice played another lane: it stops there */
        L->owner = 0;
    L = &K[lane];
    if (u) {                                             /* ((2.0, #35) a user kit: the lane's sample, from its start */
        L->st = (int8_t)st;
        L->owner = (uint8_t)(i + 1u);
        v->s[0] = (int32_t)lane;
        v->s[5] = (int32_t)drum_user_zone(u - 1u, lane);
        v->ph[0] = v->ph[1] = v->ph[2] = 0;
        v->s[1] = v->s[2] = v->s[3] = 0;
        v->s[6] = !v->s[5];                              /* (no sample: ended, the lane silent) */
        v->s[7] = 1 << 24;
        v->env_out = v->vel * 258;
        v->env = 1 << 24;
        if (lane == DV_HATC && K[DV_HATO].owner && t->v[K[DV_HATO].owner - 1u].active &&
            !t->v[K[DV_HATO].owner - 1u].s[6])
            t->v[K[DV_HATO].owner - 1u].s[6] = 2;       /* (the open hat fades out: drum_smp) */
        return;
    }
    if (L->role != role || L->v.type != dv_run_type(role)) {   /* another drum on this lane: from rest */
        dv_init(&L->v, role);
        L->key.type = 0xFF;
        L->role = (uint8_t)role;
    }
    L->st = (int8_t)st;
    L->owner = (uint8_t)(i + 1u);                        /* (its last voice, if another, ends: drum_amp) */
    v->s[0] = (int32_t)lane;
    v->env_out = v->vel * 258;                           /* the hit starts at its level (no ramp from 0) */
    v->env = 1 << 24;                                    /* the ADSR held at full from here, not from drum_amp:
                                                          * a key-off before the first block (zero-length MIDI
                                                          * notes) would end a fresh voice at env 0 in env_tick */
    dv_trigger(&L->v);
    if (lane == DV_HATC && K[DV_HATO].v.live)            /* a closed hat chokes the open one */
        dv_choke(&K[DV_HATO].v);
}

static void fm6_note_on(track_t *t, voice_t *v)
{
    fm6_note_t *n = fm6_note_of(t, v);
    uint32_t tr = (uint32_t)(t - trk);
    const uint8_t *p;
    if (!n)
        return;
    fm6_sync(t);
    p = fm6_eff[tr].p;
    fm6_note_init(n, p, (int32_t)v->note + p[FP_TRNSP] - 24, v->mvel ? v->mvel : v->vel,
                  (!v->env && !v->env_out) || !n->live);    /* from silence: phases and gains from 0 */
    fm6_lfo_key(&fm6_lfo[tr]);
}

static void graph_dx(const track_t *t, uint16_t c)
{
    const dx_lane_t *L = &dx_kit[dx_ui_lane & 7u];
    uint32_t i, w = dx_ui_win % DX_NWIN, m = L->mode;
    int32_t rh = ((int32_t)cv_h - 36) / (int32_t)DX_ROWS, y0 = 34, y, span;
    uint16_t band = ux_mix(cv_bg, c, 22);
    char b[40];
    const char *unit;
    if (rh > 14)
        rh = 14;
    for (i = 0; i < 8u; i++) {                           /* the kit's sounds, the one edited in the track's colour */
        int32_t x = 9 + (int32_t)i * (DX_TW + 2);
        int on = i == (dx_ui_lane & 7u);
        uint16_t f = on ? c : T_RAISE;
        cv_rect(x, 4, DX_TW, 16, f);
        GFX_HOOK_ALIGN(x, 4, x + DX_TW, 20, AL_HV, "DRUM-X sound name centred in its tile");
        cv_text_in(x, 4 + CAP_IN(S, 16), DX_TW, &AF_S, DX_LANE_ABBR[i], on ? T_INK : T_MID, f);
    }
    GFX_HOOK_ALIGN(DX_AX, 22, DX_AX + DX_BW, 34, AL_HV, "DRUM-X sheet's A over its bars");
    cv_text_in(DX_AX, 22 + CAP_IN(S, 12), DX_BW, &AF_S, "A", T_MID, cv_bg);
    GFX_HOOK_ALIGN(DX_BX, 22, DX_BX + DX_BW, 34, AL_HV, "DRUM-X sheet's B over its bars");
    cv_text_in(DX_BX, 22 + CAP_IN(S, 12), DX_BW, &AF_S, "B", T_MID, cv_bg);
    for (i = 0; i < DX_NROW[w]; i++) {                   /* the knobs' rows: a band, a mark */
        y = y0 + (int32_t)(DX_ROW0[w] + i) * rh;
        cv_rect(3, y, 231, rh, band);
        cv_rect(3, y, 2, rh, c);
    }
    for (i = 0; i < DX_ROWS; i++) {
        int on = i >= DX_ROW0[w] && i < DX_ROW0[w] + DX_NROW[w];
        uint16_t bg = on ? band : cv_bg;
        y = y0 + (int32_t)i * rh;
        GFX_HOOK_ALIGN(0, y, 0, y + rh, AL_V, "DRUM-X sheet label on its row's middle");
        cv_text_on(10, y + CAP_IN(S, rh), &AF_S, i < DXP_N ? DX_VAL[i] : i == 5u ? "LEVEL" : "MODE", on ? T_TEXT : T_MID, bg);
        if (i < DXP_N) {                                 /* a value: A and B */
            fmt_int(b, L->a[i]);
            dx_row_bar(DX_AX, DX_BW, y, rh, L->a[i], c, bg, b);
            fmt_int(b, L->b[i]);
            dx_row_bar(DX_BX, DX_BW, y, rh, L->b[i], T_TEXT, bg, b);
        } else if (i == 5u) {                            /* the lane's level (as LANES shows it: 100 %), DRV */
            int16_t v = t->p[P_LN0 + (dx_ui_lane & 7u)];
            param_format(&TP[P_LN0 + (dx_ui_lane & 7u)], v, b, &unit);
            str_cpy(b + str_len(b), unit, sizeof b - str_len(b));
            dx_row_bar(DX_AX, DX_BW - 8, y, rh, (uint32_t)clamp(v, 0, 127), T_MID, bg, b);
            GFX_HOOK_ALIGN(0, y, 0, y + rh, AL_V, "DRUM-X sheet DRV on its row's middle");
            cv_text_on(cv_text_on(DX_BX, y + CAP_IN(S, rh), &AF_S, "DRIVE", T_MID, bg) + 8, y + CAP_IN(S, rh), &AF_S,
                       m & DX_DRIVE ? "ON" : "OFF", m & DX_DRIVE ? T_TEXT : T_DIM, bg);
        } else {                                         /* the switches, in words */
            str_cpy(b, DX_WAVE[m & 3u], sizeof b);
            str_cpy(b + str_len(b), "  ", sizeof b - str_len(b));
            str_cpy(b + str_len(b), DX_FILT[((m >> 2) & 3u) % 3u], sizeof b - str_len(b));
            str_cpy(b + str_len(b), (m >> 4) & 1u ? "  SNAP ON  PMOD " : "  SNAP OFF  PMOD ", sizeof b - str_len(b));
            str_cpy(b + str_len(b), DX_PMOD[(m >> 5) & 3u], sizeof b - str_len(b));
            GFX_HOOK_ALIGN(0, y, 0, y + rh, AL_V, "DRUM-X sheet switches on their row's middle");
            cv_text_on(DX_AX, y + CAP_IN(S, rh), &AF_S, b, on ? T_TEXT : T_MID, bg);
        }
    }
    span = (int32_t)DX_ROWS * rh;                        /* where the knobs are on the sheet */
    cv_rect(236, y0, 2, span, T_RAISE);
    cv_rect(236, y0 + (int32_t)DX_ROW0[w] * rh, 2, (int32_t)DX_NROW[w] * rh, T_MID);
}

/* field f's byte in the patch (operator fm_ui[0] on OPERATOR) */
static uint32_t fm_at(uint32_t pg, const fm_field_t *f)
{
    return pg ? f->off : (5u - fm_ui[0] % 6u) * FP_OP + f->off;
}

/* tenths: "-1.5", "5.5", "+0.4" (sign: a plus too) */
static void fm_tenths(char *b, int32_t v, int sign)
{
    if (v < 0)
        *b++ = '-';
    else if (sign && v > 0)
        *b++ = '+';
    v = v < 0 ? -v : v;
    fmt_int(b, v / 10);
    b += str_len(b);
    *b++ = '.';
    *b++ = (char)('0' + v % 10);
    *b = 0;
}

/* log2 x, Q16 (x > 0): the exponent, the mantissa's log2 ~ f + 0.34 f (1 - f) (within 0.004) */
static int32_t fm_log2(uint32_t x)
{
    int32_t e = 0;
    uint32_t f;
    while (x >= 2u << e && e < 31)
        e++;
    f = (e > 16 ? x >> (e - 16) : x << (16 - e)) - 65536u;
    return (e << 16) + (int32_t)f + (int32_t)(((f >> 1) * ((65536u - f) >> 1) >> 14) * 22u >> 6);
}
